pragma solidity =0.6.12;

abstract contract Adminable {

    /**
     * @dev Upper bound on the address count accepted by {setFeeExemptBatch}.
     * Kept well under the block gas limit so a full batch can never become
     * unminable: ~25k gas per entry * 100 ~= 2.5M gas.
     */
    uint16 public constant MAX_BATCH_SIZE_LIMIT = 100;

    /**
     * @dev Implemented by the child contract to define the admin.
     */
    function _authorize() internal view virtual;

    modifier onlyAdmin() {
        _authorize();
        _;
    }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

import "./Adminable.sol";

abstract contract Blacklistable is Adminable {

    mapping(address => bool) public blacklist;

    /**
     * @dev If false, blacklist is ignored and all users can swap freely.
     */
    bool public blacklistOn;

    event BlacklistSet(address indexed user, bool blocked);
    event BlacklistOnSet(bool on);

    constructor() internal {
        blacklistOn = true;
    }

    /**
     * @dev Set whether a user is blocked from swapping while blacklistOn is true.
     * @param user User address.
     * @param blocked Blacklist flag.
     */
    function setBlacklist(address user, bool blocked) external onlyAdmin {
        _setBlacklist(user, blocked);
    }

    /**
     * @dev Batch {setBlacklist}: applies `blocked` to every address in `users`.
     * The shared guard rejects zero addresses, no-op entries, and duplicates.
     * @param users Addresses to update (1..MAX_BATCH_SIZE_LIMIT).
     * @param blocked Blacklist flag applied to all of them.
     */
    function setBlacklistBatch(address[] calldata users, bool blocked) external onlyAdmin {
        uint256 len = users.length;
        require(len != 0, "Blacklistable: EMPTY_BATCH");
        require(len <= MAX_BATCH_SIZE_LIMIT, "Blacklistable: BATCH_TOO_LARGE");

        for (uint256 i = 0; i < len; i++) {
            _setBlacklist(users[i], blocked);
        }
    }

    /**
     * @dev Toggle blacklist checks globally.
     */
    function setBlacklistOn(bool on) external onlyAdmin {
        blacklistOn = on;
        emit BlacklistOnSet(on);
    }

    /**
     * @dev Shared blacklist write, reused by the single and batch setters.
     */
    function _setBlacklist(address user, bool blocked) private {
        require(user != address(0), "Blacklistable: ZERO_ADDRESS");
        require(blocked != blacklist[user], "Blacklistable: ALREADY_SET");

        blacklist[user] = blocked;
        emit BlacklistSet(user, blocked);
    }

    /**
     * @dev Effective blacklist check.
     */
    function isBlacklisted(address user) public view virtual returns (bool) {
        return blacklistOn && blacklist[user];
    }
}

