pragma solidity =0.6.12;

import "./Adminable.sol";
import "../libraries/SafeMath.sol";

abstract contract SwapLimitable is Adminable {
    using SafeMath for uint256;

    /// @dev Rolling window used by each user/token swap cap bucket.
    uint256 public constant SWAP_LIMIT_PERIOD = 24 hours;

    /// @dev Buckets store cap usage in uint192 so each bucket fits in one storage slot.
    uint192 public constant MAX_SWAP_LIMIT_CAP = uint192(-1);

    /// @dev Users that bypass swap cap checks while swapLimitOn is enabled.
    mapping(address => bool) public swapLimitExempt;

    /// @dev If false, all swap cap checks are skipped.
    bool public swapLimitOn;

    /// @dev Per-user, per-token rolling cap bucket.
    struct Bucket {
        uint64 periodStart;
        uint192 capUsed;
    }

    /// @dev user => token => rolling cap bucket.
    mapping(address => mapping(address => Bucket)) public buckets;

    /// @dev token => 24h cap. A zero cap means the token is not limited.
    mapping(address => uint256) public caps;

    event SwapLimitExemptSet(address indexed user, bool allowed);
    event SwapLimitOnSet(bool on);
    event SwapLimitTokenSet(address indexed token, uint256 cap);
    event SwapLimitUsed(address indexed user, address indexed token, uint256 amount, uint256 capUsed, uint256 cap, uint64 periodStart);

    constructor() internal {
        swapLimitOn = false;
    }

    /**
     * @dev Toggle swap cap checks globally.
     */
    function setSwapLimitOn(bool on) external onlyAdmin {
        swapLimitOn = on;
        emit SwapLimitOnSet(on);
    }

    /**
     * @dev Batch {setSwapLimitExempt}: applies `allowed` to every address in `users`.
     * @param users Addresses to update (1..MAX_BATCH_SIZE_LIMIT).
     * @param allowed Swap cap exemption flag applied to all of them.
     */
    function setSwapLimitExemptBatch(address[] calldata users, bool allowed) external onlyAdmin {
        uint256 len = users.length;
        require(len != 0, "SwapLimitable: EMPTY_BATCH");
        require(len <= MAX_BATCH_SIZE_LIMIT, "SwapLimitable: BATCH_TOO_LARGE");

        for (uint256 i = 0; i < len; i++) {
            _setSwapLimitExempt(users[i], allowed);
        }
    }

    /**
     * @dev Set whether a user bypasses swap cap checks while swapLimitOn is true.
     * @param user User address.
     * @param allowed Swap cap exemption flag.
     */
    function setSwapLimitExempt(address user, bool allowed) external onlyAdmin {
        _setSwapLimitExempt(user, allowed);
    }

    /**
     * @dev Set per-token 24h swap caps. Passing cap = 0 disables the token cap.
     * @param tokens Tokens whose input volume should be capped.
     * @param _caps 24h caps for each token, in the token's own decimals.
     */
    function setSwapLimitTokens(address[] calldata tokens, uint256[] calldata _caps) external onlyAdmin {
        uint256 len = tokens.length;
        require(len != 0 && len == _caps.length, "SwapLimitable: INVALID_LENGTH");
        require(len <= MAX_BATCH_SIZE_LIMIT, "SwapLimitable: BATCH_TOO_LARGE");

        for (uint256 i = 0; i < len; i++) {
            address token = tokens[i];
            uint256 cap = _caps[i];

            require(token != address(0), "SwapLimitable: ZERO_ADDRESS");
            require(cap <= MAX_SWAP_LIMIT_CAP, "SwapLimitable: CAP_TOO_LARGE");
            require(cap != caps[token], "SwapLimitable: ALREADY_SET");

            for (uint256 j = 0; j < i; j++) {
                require(token != tokens[j], "SwapLimitable: DUPLICATE_TOKEN");
            }

            caps[token] = cap;
            emit SwapLimitTokenSet(token, cap);
        }
    }

    /**
     * @dev Apply configured caps to every tokenIn in a swap path.
     */
    function _swapLimits(address user, address[] calldata path, uint256[] calldata amounts) internal {
        if (!swapLimitOn || isSwapLimitExempt(user)) return;

        for (uint256 i = 0; i < path.length - 1; i++) {
            address tokenIn = path[i];
            _swapLimit(user, tokenIn, amounts[i], caps[tokenIn]);
        }
    }

    /**
     * @dev Apply one token cap. A zero cap disables the token and exits without state changes.
     */
    function _swapLimit(address user, address token, uint256 amount, uint256 cap) private {
        if (cap == 0) return;

        Bucket storage bucket = buckets[user][token];

        if (bucket.periodStart == 0 || block.timestamp >= uint256(bucket.periodStart).add(SWAP_LIMIT_PERIOD)) {
            bucket.periodStart = uint64(block.timestamp);
            bucket.capUsed = 0;
        }

        uint256 newCapUsed = uint256(bucket.capUsed).add(amount);
        require(newCapUsed <= cap, "SwapLimitable: CAP_EXCEEDED");

        bucket.capUsed = uint192(newCapUsed);

        emit SwapLimitUsed(user, token, amount, newCapUsed, cap, bucket.periodStart);
    }

    /**
     * @dev Shared swap cap exemption write, reused by the single and batch setters.
     */
    function _setSwapLimitExempt(address user, bool allowed) private {
        require(user != address(0), "SwapLimitable: ZERO_ADDRESS");
        require(allowed != swapLimitExempt[user], "SwapLimitable: ALREADY_SET");

        swapLimitExempt[user] = allowed;
        emit SwapLimitExemptSet(user, allowed);
    }

    /**
     * @dev Effective swap cap exemption check.
     */
    function isSwapLimitExempt(address user) public view virtual returns (bool) {
        return swapLimitOn && swapLimitExempt[user];
    }
}

